$clear = function (string $what) use ($self) { ?><form method="post" action="<?= $self ?>" class="inline" data-lock><?= csrf_field() ?><input type="hidden" name="action" value="perf_clear"><input type="hidden" name="what" value="<?= e($what) ?>"><button class="btn btn--ghost btn--sm" type="submit" data-js-confirm="<?= tt('ph.clear_q') ?>">🧹 <?= tt('ph.clear') ?></button></form><?php };
