?>
<div class="page-head"><h1>🩺 <?= tt('ph.title') ?></h1><div class="btn-row"><a class="btn btn--ghost btn--sm" href="<?= url('admin_about', ['diag' => 1]) ?>#diag">▶ <?= tt('dg.title') ?></a></div></div>
<p class="hint" style="margin:0 0 6px;"><?= tt('ph.lede') ?></p>
<div class="tabs" style="margin:6px 0 12px;"><?php foreach ($tabs as $k => $l): ?><a href="<?= url('admin_health', ['tab' => $k]) ?>"<?= $k === $tab ? ' class="is-on"' : '' ?>><?= e($l) ?></a><?php endforeach; ?></div>

<?php if ($tab === 'trend'):
  $T = perf_trend(30); $pg = preg_replace('/[^a-z0-9_.]/', '', (string)($_GET['pg'] ?? ''));
  $ser = []; foreach ($T as $day => $d) { $r = $pg !== '' ? ($d['pages'][$pg] ?? null) : $d['all']; $ser[$day] = $r ?: ['n' => 0, 'p50' => 0, 'p95' => 0, 'max' => 0, 'q' => 0, 'db' => 0]; }
  $pagesAgg = []; foreach (array_slice($T, -7, null, true) as $d) foreach ($d['pages'] as $k => $r) { $b = &$pagesAgg[$k]; $b = $b ?? ['n' => 0, 'w50' => 0, 'p95' => 0, 'max' => 0, 'q' => 0]; $b['n'] += $r['n']; $b['w50'] += $r['p50'] * $r['n']; $b['p95'] = max($b['p95'], $r['p95']); $b['max'] = max($b['max'], $r['max']); $b['q'] = max($b['q'], $r['q']); unset($b); }
  uasort($pagesAgg, fn($a, $b) => $b['w50'] <=> $a['w50']); ?>
<div class="card"><div class="card-head"><h2>📈 <?= tt('ph.trend_h') ?><?= $pg !== '' ? ' — ' . e($pg) : '' ?></h2><?php if ($pg !== ''): ?><a class="btn btn--ghost btn--sm" href="<?= url('admin_health', ['tab' => 'trend']) ?>">✕ <?= tt('ph.all_pages') ?></a><?php endif; ?></div>
  <p class="hint" style="margin:0 0 8px;"><?= tt('ph.trend_hint') ?></p>
  <?php $days = array_keys($ser); $nD = count($days); $vals = array_filter(array_merge(array_column($ser, 'p95'), array_column($ser, 'p50')));
  if ($nD < 2 || !$vals): ?><p class="hint"><?= tt('ph.trend_none') ?></p><?php else:
    $W = 920; $H = 250; $pl = 56; $pr = 70; $pt = 14; $pb = 30; $max = max($vals); $step = max(50, (int) (10 ** floor(log10(max(1, $max))))); if ($max / $step < 3) $step = (int) max(10, $step / 2); $top = (int) (ceil($max / $step) * $step);
    $x = fn($i) => $pl + ($W - $pl - $pr) * ($nD > 1 ? $i / ($nD - 1) : 0); $y = fn($v) => $pt + ($H - $pt - $pb) * (1 - $v / max(1, $top));
    $path = function (string $k) use ($ser, $days, $x, $y) { $d = ''; $pen = false; foreach ($days as $i => $day) { if (!$ser[$day]['n']) { $pen = false; continue; } $d .= ($pen ? 'L' : 'M') . round($x($i), 1) . ' ' . round($y($ser[$day][$k]), 1) . ' '; $pen = true; } return $d; };
    $lastI = $nD - 1; while ($lastI > 0 && !$ser[$days[$lastI]]['n']) $lastI--; ?>
  <div style="overflow-x:auto;"><svg viewBox="0 0 <?= $W ?> <?= $H ?>" width="100%" style="max-width:<?= $W ?>px;min-width:560px;height:auto;display:block;" role="img" aria-label="<?= tt('ph.trend_h') ?>">
    <?php for ($g = 0; $g <= $top; $g += $step): ?><line x1="<?= $pl ?>" x2="<?= $W - $pr ?>" y1="<?= round($y($g), 1) ?>" y2="<?= round($y($g), 1) ?>" style="stroke:currentColor;opacity:.13"/><text x="<?= $pl - 8 ?>" y="<?= round($y($g) + 4, 1) ?>" text-anchor="end" style="font-size:11px;fill:currentColor;opacity:.7"><?= number_format($g, 0, ',', '.') ?></text><?php endfor; ?>
    <?php foreach ($days as $i => $day): if ($i % max(1, (int) ceil($nD / 10)) === 0 || $i === $nD - 1): ?><text x="<?= round($x($i), 1) ?>" y="<?= $H - 10 ?>" text-anchor="middle" style="font-size:11px;fill:currentColor;opacity:.7"><?= e(date('d/m', (int) strtotime($day))) ?></text><?php endif; endforeach; ?>
    <path d="<?= $path('p95') ?>" style="fill:none;stroke:var(--gold-deep);stroke-width:2.2;stroke-dasharray:6 4"/><path d="<?= $path('p50') ?>" style="fill:none;stroke:var(--green);stroke-width:2.4"/>
    <?php foreach ($days as $i => $day): if (!$ser[$day]['n']) continue; ?><circle cx="<?= round($x($i), 1) ?>" cy="<?= round($y($ser[$day]['p95']), 1) ?>" r="2.6" style="fill:var(--gold-deep)"><title><?= e($day . ' · ' . t('ph.p95') . ' ' . $ser[$day]['p95'] . ' ms') ?></title></circle><circle cx="<?= round($x($i), 1) ?>" cy="<?= round($y($ser[$day]['p50']), 1) ?>" r="2.8" style="fill:var(--green)"><title><?= e($day . ' · ' . t('ph.p50') . ' ' . $ser[$day]['p50'] . ' ms') ?></title></circle><?php endforeach; ?>
    <text x="<?= round($x($lastI) + 8, 1) ?>" y="<?= round($y($ser[$days[$lastI]]['p95']) - 5, 1) ?>" style="font-size:11px;font-weight:600;fill:var(--gold-deep)"><?= tt('ph.p95') ?></text>
    <text x="<?= round($x($lastI) + 8, 1) ?>" y="<?= round($y($ser[$days[$lastI]]['p50']) + 13, 1) ?>" style="font-size:11px;font-weight:600;fill:var(--green)"><?= tt('ph.p50') ?></text>
    <text x="<?= $pl ?>" y="10" style="font-size:10px;fill:currentColor;opacity:.7">ms</text>
  </svg></div>
  <?php endif; ?>
  <div class="table-scroll" style="margin-top:10px;"><table class="tbl tbl--compact"><thead><tr><th><?= tt('th.date') ?></th><th class="num"><?= tt('ph.c_pages') ?></th><th class="num"><?= tt('ph.p50') ?></th><th class="num"><?= tt('ph.p95') ?></th><th class="num"><?= tt('ph.c_max') ?></th><th class="num"><?= tt('ph.c_q') ?></th><th class="num"><?= tt('ph.c_db') ?></th><?php if ($pg === ''): ?><th class="num"><?= tt('ph.c_out') ?></th><?php endif; ?></tr></thead><tbody>
  <?php foreach (array_reverse($ser, true) as $day => $r): ?><tr><td class="date"><?= e(date('d/m/Y', (int) strtotime($day))) ?></td><td class="num"><?= (int)$r['n'] ?></td><td class="num"><?= $r['n'] ? $ms($r['p50']) : '—' ?></td><td class="num"><?= $r['n'] ? $ms($r['p95']) : '—' ?></td><td class="num"><?= $r['n'] ? $ms($r['max']) : '—' ?></td><td class="num"><?= $r['n'] ? (int)$r['q'] : '—' ?></td><td class="num"><?= $r['n'] ? $ms($r['db']) : '—' ?></td><?php if ($pg === ''): ?><td class="num"><?= $r['n'] ? $ms($r['out'] ?? 0) : '—' ?></td><?php endif; ?></tr><?php endforeach; ?>
  </tbody></table></div>
</div>
<div class="card"><div class="card-head"><h2>📄 <?= tt('ph.pages7') ?></h2><?php $clear('trend'); ?></div><p class="hint" style="margin:0 0 8px;"><?= tt('ph.pages7_hint') ?></p>
  <?php if (!$pagesAgg): ?><p class="hint"><?= tt('ph.trend_none') ?></p><?php else: ?><div class="table-scroll"><table class="tbl tbl--compact"><thead><tr><th><?= tt('ph.c_page') ?></th><th class="num"><?= tt('ph.c_times') ?></th><th class="num"><?= tt('ph.p50') ?></th><th class="num"><?= tt('ph.p95') ?></th><th class="num"><?= tt('ph.c_max') ?></th><th class="num"><?= tt('ph.c_q') ?></th><th class="num"><?= tt('ph.c_total') ?></th></tr></thead><tbody>
  <?php foreach (array_slice($pagesAgg, 0, 40, true) as $k => $r): ?><tr><td><a href="<?= url('admin_health', ['tab' => 'trend', 'pg' => $k]) ?>"><?= e((string)$k) ?></a></td><td class="num"><?= (int)$r['n'] ?></td><td class="num"><?= $ms($r['w50'] / max(1, $r['n'])) ?></td><td class="num"><?= $ms($r['p95']) ?></td><td class="num"><?= $ms($r['max']) ?></td><td class="num"><?= (int)$r['q'] ?></td><td class="num"><?= number_format($r['w50'] / 1000, 0, ',', '.') ?> s</td></tr><?php endforeach; ?>
  </tbody></table></div><?php endif; ?>
</div>

<?php elseif ($tab === 'pages'): $rows = db_slow_pages(60); usort($rows, fn($a, $b) => strcmp($b['at'], $a['at'])); ?>
<div class="card"><h2>🐢 <?= tt('ph.pages_h') ?> <span class="count"><?= count($rows) ?></span></h2><p class="hint" style="margin:0 0 8px;"><?= tt('ph.pages_hint') ?></p>
  <?php if (!$rows): ?><p class="hint"><?= tt('dg.slow_none') ?></p><?php else: ?><div class="table-scroll"><table class="tbl tbl--compact"><thead><tr><th><?= tt('ph.c_when') ?></th><th><?= tt('ph.c_page') ?></th><th class="num"><?= tt('ph.c_total') ?></th><th style="min-width:220px;"><?= tt('ph.c_where') ?></th><th class="num"><?= tt('ph.c_boot') ?></th><th class="num"><?= tt('ph.c_prep') ?></th><th class="num"><?= tt('ph.c_render') ?></th><th class="num"><?= tt('ph.c_db') ?></th><th class="num"><?= tt('ph.c_out') ?></th><th class="num"><?= tt('ph.c_q') ?></th><th><?= tt('ph.c_stmt') ?></th></tr></thead><tbody>
  <?php foreach ($rows as $r): $ph = $r['ph']; $tot = max(1, $r['ms']); $out = (int)($ph['out'] ?? 0); $php = max(0, $r['ms'] - $r['db'] - $out); ?>
  <tr><td class="date"><?= e($when($r['at'])) ?></td><td><?= e($r['page']) ?></td><td class="num"><b><?= $ms($r['ms']) ?></b></td>
    <td><?php if ($ph): ?><div style="display:flex;height:12px;border-radius:6px;overflow:hidden;border:1px solid var(--line);" title="<?= e(t('ph.c_db') . ' ' . $r['db'] . ' ms · ' . t('ph.c_out') . ' ' . $out . ' ms · ' . t('ph.c_php') . ' ' . $php . ' ms') ?>"><span style="width:<?= round($r['db'] / $tot * 100, 1) ?>%;background:var(--navy-3);"></span><span style="width:<?= round($out / $tot * 100, 1) ?>%;background:var(--gold);"></span><span style="width:<?= round($php / $tot * 100, 1) ?>%;background:var(--green);"></span></div><?php else: ?><span class="hint">—</span><?php endif; ?></td>
    <td class="num"><?= $ph ? $ms($ph['boot'] ?? 0) : '—' ?></td><td class="num"><?= $ph ? $ms($ph['prep'] ?? 0) : '—' ?></td><td class="num"><?= $ph ? $ms($ph['render'] ?? 0) : '—' ?></td><td class="num"><?= $ms($r['db']) ?></td><td class="num"><?= $ph ? $ms($out) . ((int)($ph['outn'] ?? 0) ? ' (' . (int)$ph['outn'] . ')' : '') : '—' ?></td><td class="num"><?= (int)$r['q'] ?></td><td class="mono hint" style="max-width:340px;"><?= e(mb_substr((string)$r['slow'], 0, 200)) ?></td></tr>
  <?php endforeach; ?></tbody></table></div>
  <p class="hint" style="margin-top:8px;"><span style="display:inline-block;width:10px;height:10px;background:var(--navy-3);border-radius:2px;"></span> <?= tt('ph.c_db') ?> &nbsp; <span style="display:inline-block;width:10px;height:10px;background:var(--gold);border-radius:2px;"></span> <?= tt('ph.c_out') ?> &nbsp; <span style="display:inline-block;width:10px;height:10px;background:var(--green);border-radius:2px;"></span> <?= tt('ph.c_php') ?></p><?php endif; ?>
</div>

<?php elseif ($tab === 'out'): $rows = perf_out_summary(24); ?>
<div class="card"><div class="card-head"><h2>🌐 <?= tt('ph.out_h') ?> <span class="count"><?= count($rows) ?></span></h2><?php $clear('out'); ?></div><p class="hint" style="margin:0 0 8px;"><?= tt('ph.out_hint') ?></p>
  <?php if (!$rows): ?><p class="hint"><?= tt('ph.none24') ?></p><?php else: ?><div class="table-scroll"><table class="tbl tbl--compact"><thead><tr><th><?= tt('ph.c_what') ?></th><th><?= tt('ph.c_host') ?></th><th class="num"><?= tt('ph.c_calls') ?></th><th class="num"><?= tt('ph.c_fail') ?></th><th class="num"><?= tt('ph.c_avg') ?></th><th class="num"><?= tt('ph.c_max') ?></th><th class="num"><?= tt('ph.c_total') ?></th><th><?= tt('ph.c_last') ?></th><th><?= tt('ph.c_lastfail') ?></th><th><?= tt('ph.c_from') ?></th></tr></thead><tbody>
  <?php foreach ($rows as $r): ?><tr><td><b><?= e($r['what']) ?></b></td><td class="mono"><?= e($r['host']) ?></td><td class="num"><?= (int)$r['n'] ?></td><td class="num"><?= $r['fail'] ? pill('bad', (string)$r['fail']) : pill('green', '0') ?></td><td class="num"><?= $ms($r['sum'] / max(1, $r['n'])) ?></td><td class="num"><?= $ms($r['max']) ?></td><td class="num"><?= number_format($r['sum'] / 1000, 1, ',', '.') ?> s</td><td class="date"><?= e($when($r['last'])) ?></td><td class="hint"><?= e($r['last_fail'] ? $when(substr($r['last_fail'], 0, 19)) . substr($r['last_fail'], 19) : '—') ?></td><td class="hint"><?= e(implode(', ', array_slice(array_keys($r['pages']), 0, 4))) ?></td></tr><?php endforeach; ?>
  </tbody></table></div><?php endif; ?>
</div>

<?php elseif ($tab === 'jobs'): $J = perf_jobs(); $S = $J['_sweep'] ?? null; unset($J['_sweep']);
  $names = ['notifications' => 'ph.j_notifications', 'task_reminders' => 'ph.j_task_reminders', 'permit_expiry' => 'ph.j_permit_expiry', 'licence' => 'ph.j_licence', 'hr_assistant' => 'ph.j_hr_assistant', 'recruiting_retention' => 'ph.j_recruiting_retention', 'website_statistics' => 'ph.j_website_statistics', 'contacts_once' => 'ph.j_contacts_once', 'newsletters' => 'ph.j_newsletters', 'news_feeds' => 'ph.j_news_feeds', 'health_report' => 'ph.j_health_report'];
  $sched = ['notifications' => 'ph.s_minute', 'task_reminders' => 'ph.s_minute', 'permit_expiry' => 'ph.s_minute', 'licence' => 'ph.s_minute', 'hr_assistant' => 'ph.s_minute', 'recruiting_retention' => 'ph.s_daily', 'website_statistics' => 'ph.s_15', 'contacts_once' => 'ph.s_once', 'newsletters' => 'ph.s_nl', 'news_feeds' => 'ph.s_feeds', 'health_report' => 'ph.s_health']; ?>
<div class="card"><div class="card-head"><h2>⚙ <?= tt('ph.jobs_h') ?></h2><?php $clear('jobs'); ?></div><p class="hint" style="margin:0 0 8px;"><?= tt('ph.jobs_hint') ?></p>
  <?php if ($S): $age = time() - (int) strtotime((string)$S['at']); ?><p style="margin:0 0 10px;"><?= $age > 3600 ? pill('gold', t('ph.sweep_old')) : pill('green', 'OK') ?> <?= e(t('ph.sweep_line', ['at' => $when($S['at']), 'ms' => $S['ms'], 'max' => $S['max'], 'mode' => $S['mode'] === 'after the page' ? t('ph.mode_after') : ($S['mode'] === 'background call' ? t('ph.mode_bg') : t('ph.mode_page')), 'runs' => $S['runs']])) ?></p><?php endif; ?>
  <?php if (!$J): ?><p class="hint"><?= tt('ph.jobs_none') ?></p><?php else: ?><div class="table-scroll"><table class="tbl tbl--compact"><thead><tr><th><?= tt('ph.c_job') ?></th><th><?= tt('ph.c_sched') ?></th><th><?= tt('ph.c_lastwork') ?></th><th class="num"><?= tt('ph.c_dur') ?></th><th class="num"><?= tt('ph.c_done') ?></th><th><?= tt('ph.c_result') ?></th><th class="num"><?= tt('ph.c_max') ?></th><th class="num"><?= tt('ph.c_runs') ?></th><th class="num"><?= tt('ph.c_fail') ?></th><th><?= tt('ph.c_lasterr') ?></th></tr></thead><tbody>
  <?php foreach ($J as $k => $j): ?><tr><td><b><?= e(isset($names[$k]) ? t($names[$k]) : (string)$k) ?></b></td><td class="hint"><?= e(isset($sched[$k]) ? ($k === 'health_report' && function_exists('dh_time') ? t('ph.s_health', ['t' => dh_on() ? dh_time() : '—']) : t($sched[$k])) : '') ?></td><td class="date"><?= e($when($j['at'] ?? '')) ?></td><td class="num"><?= $ms($j['ms'] ?? 0) ?></td><td class="num"><?= (int)($j['n'] ?? 0) ?: '—' ?></td><td><?= !empty($j['ok']) ? pill('green', 'OK') : pill('bad', t('dg.fail')) ?></td><td class="num"><?= $ms($j['max'] ?? 0) ?></td><td class="num"><?= (int)($j['runs'] ?? 0) ?></td><td class="num"><?= (int)($j['fails'] ?? 0) ?: '—' ?></td><td class="hint"><?= e(!empty($j['err']) ? $when($j['err_at'] ?? '') . ' · ' . $j['err'] : '—') ?></td></tr><?php endforeach; ?>
  </tbody></table></div><?php endif; ?>
</div>

<?php elseif ($tab === 'sql'): $D = perf_sql_digest(7); $xh = preg_replace('/[^a-f0-9]/', '', (string)($_GET['x'] ?? '')); $X = $xh !== '' ? perf_sql_explain($xh) : null; ?>
<?php if ($X): ?><div class="card" id="explain"><div class="card-head"><h2>🔎 <?= tt('ph.explain_h') ?></h2><a class="btn btn--ghost btn--sm" href="<?= url('admin_health', ['tab' => 'sql']) ?>">✕ <?= tt('btn.cancel') ?></a></div>
  <?php if (!empty($X['err'])): ?><p class="hint"><?= e($X['err'] === 'select' ? t('ph.explain_select') : ($X['err'] === 'not found' ? t('ph.explain_gone') : $X['err'])) ?></p><?php else: ?>
  <p class="mono" style="word-break:break-word;margin:0 0 8px;"><?= e($X['sql']) ?></p>
  <?php foreach ($X['hints'] as [$tone, $tbl, $kind, $n]): ?><p style="margin:0 0 4px;"><?= pill($tone === 'bad' ? 'bad' : 'gold', $tbl) ?> <?= e(t('ph.hint_' . $kind, ['n' => number_format($n, 0, ',', '.')])) ?></p><?php endforeach; if (!$X['hints']): ?><p style="margin:0 0 4px;"><?= pill('green', 'OK') ?> <?= tt('ph.hint_ok') ?></p><?php endif; ?>
  <div class="table-scroll"><table class="tbl tbl--compact"><thead><tr><?php foreach (['table', 'type', 'possible_keys', 'key', 'rows', 'Extra'] as $c): ?><th><?= e($c) ?></th><?php endforeach; ?></tr></thead><tbody><?php foreach ($X['rows'] as $r): ?><tr><?php foreach (['table', 'type', 'possible_keys', 'key', 'rows', 'Extra'] as $c): ?><td class="mono"><?= e((string)($r[$c] ?? '')) ?></td><?php endforeach; ?></tr><?php endforeach; ?></tbody></table></div>
  <p class="hint" style="margin-top:6px;"><?= tt('ph.explain_note') ?></p><?php endif; ?></div><?php endif; ?>
<div class="card"><div class="card-head"><h2>🗄 <?= tt('ph.sql_h') ?> <span class="count"><?= count($D) ?></span></h2><?php $clear('sql'); ?></div><p class="hint" style="margin:0 0 8px;"><?= e(t('ph.sql_hint', ['ms' => PERF_SLOW_SQL_MS])) ?></p>
  <?php if (!$D): ?><p class="hint"><?= tt('ph.sql_none') ?></p><?php else: ?><div class="table-scroll"><table class="tbl tbl--compact"><thead><tr><th><?= tt('ph.c_stmt') ?></th><th class="num"><?= tt('ph.c_times') ?></th><th class="num"><?= tt('ph.c_total') ?></th><th class="num"><?= tt('ph.c_avg') ?></th><th class="num"><?= tt('ph.c_max') ?></th><th><?= tt('ph.c_from') ?></th><th><?= tt('ph.c_last') ?></th><th></th></tr></thead><tbody>
  <?php foreach (array_slice($D, 0, 50, true) as $h => $r): arsort($r['pages']); ?><tr><td class="mono" style="max-width:560px;"><?= e(mb_substr($r['sql'], 0, 260)) ?><?= mb_strlen($r['sql']) > 260 ? '…' : '' ?></td><td class="num"><?= (int)$r['n'] ?></td><td class="num"><b><?= number_format($r['sum'] / 1000, 1, ',', '.') ?> s</b></td><td class="num"><?= $ms($r['sum'] / max(1, $r['n'])) ?></td><td class="num"><?= $ms($r['max']) ?></td><td class="hint"><?= e(implode(', ', array_slice(array_keys($r['pages']), 0, 3))) ?></td><td class="date"><?= e($when($r['last'])) ?></td><td><a class="btn btn--ghost btn--sm" href="<?= url('admin_health', ['tab' => 'sql', 'x' => $h]) ?>#explain">🔎 <?= tt('ph.explain') ?></a></td></tr><?php endforeach; ?>
  </tbody></table></div><?php endif; ?>
</div>

<?php else: $E = perf_errors(); $rel = perf_release_at(); $onlyNew = !empty($_GET['new']); $nNew = count(array_filter($E, fn($g) => $g['new'])); if ($onlyNew) $E = array_values(array_filter($E, fn($g) => $g['new'])); ?>
<div class="card"><div class="card-head"><h2>🧯 <?= tt('ph.err_h') ?> <span class="count"><?= count($E) ?></span></h2><div class="btn-row"><?php if ($onlyNew): ?><a class="btn btn--ghost btn--sm" href="<?= url('admin_health', ['tab' => 'errors']) ?>"><?= tt('ph.err_all') ?></a><?php elseif ($nNew): ?><a class="btn btn--gold btn--sm" href="<?= url('admin_health', ['tab' => 'errors', 'new' => 1]) ?>"><?= e(t('ph.err_only_new', ['n' => $nNew])) ?></a><?php endif; ?></div></div>
  <p class="hint" style="margin:0 0 8px;"><?= e(t('ph.err_hint', ['v' => CP_VERSION, 'at' => $rel ? $when($rel) : '—'])) ?></p>
  <?php if (!$E): ?><p class="hint"><?= tt('ph.err_none') ?></p><?php else: ?><div class="table-scroll"><table class="tbl tbl--compact"><thead><tr><th></th><th><?= tt('ph.c_msg') ?></th><th class="num"><?= tt('ph.c_times') ?></th><th><?= tt('ph.c_first') ?></th><th><?= tt('ph.c_last') ?></th><th><?= tt('ph.c_page') ?></th><th><?= tt('ph.c_ver') ?></th></tr></thead><tbody>
  <?php foreach (array_slice($E, 0, 120) as $g): ?><tr><td style="white-space:nowrap;"><?= $g['lvl'] === 'fatal' ? pill('bad', t('ph.l_fatal')) : ($g['lvl'] === 'warning' ? pill('gold', t('ph.l_warning')) : pill('mute', t('ph.l_' . $g['lvl']))) ?><?= $g['new'] ? ' ' . pill('bad', t('ph.new')) : (!$g['active'] ? ' ' . pill('green', t('ph.quiet')) : '') ?></td><td class="mono" style="max-width:620px;word-break:break-word;"><?= e($g['sample']) ?></td><td class="num"><b><?= (int)$g['n'] ?></b></td><td class="date"><?= e($when($g['first'])) ?></td><td class="date"><?= e($when($g['last'])) ?></td><td class="hint"><?= e(implode(', ', array_slice(array_keys($g['pages']), 0, 4)) ?: '—') ?></td><td class="hint"><?= e(implode(', ', array_slice(array_keys($g['vers']), -3)) ?: '—') ?></td></tr><?php endforeach; ?>
  </tbody></table></div><?php endif; ?>
</div>
<?php endif; ?>
<?php layout_foot();
